import express from 'express';
const app = express();

// Static assets: cache forever (Vite fingerprints filenames)
app.use('/assets', express.static('dist/assets', {
  maxAge: '1y',
  immutable: true,
  // Adds: Cache-Control: public, max-age=31536000, immutable
}));

// HTML: never serve stale
app.get('/', (req, res) => {
  res.setHeader('Cache-Control', 'public, max-age=0, must-revalidate');
  res.sendFile('dist/index.html');
});

// API: public data with stale-while-revalidate
app.get('/api/products', async (req, res) => {
  res.setHeader('Cache-Control', 'public, max-age=300, stale-while-revalidate=86400');
  const products = await db.query('SELECT * FROM products');
  res.json(products);
});

// API: private/user data — CDN must not cache
app.get('/api/user/profile', requireAuth, async (req, res) => {
  res.setHeader('Cache-Control', 'private, no-store');
  const user = await db.query('SELECT * FROM users WHERE id = $1', [req.user.id]);
  res.json(user);
});

// Vary header: tells CDN to store separate caches for different Accept-Encoding
// (prevents serving compressed content to clients that don't support gzip)
app.use((req, res, next) => {
  res.setHeader('Vary', 'Accept-Encoding');
  next();
});

PROBLEM: If you cache main.js for 1 year, how do users get the new version?

VITE'S SOLUTION: Content hashing
  Source file:  src/main.tsx
  Build output: dist/assets/main.BhJj3X.js  ← hash of file content

  When content changes: dist/assets/main.KpQr9Y.js  ← different hash

  Your index.html references the exact filename:
  <script src="/assets/main.BhJj3X.js"></script>

  When you deploy a new build:
  → index.html changes (no-cache, so browsers always get latest)
  → index.html references main.KpQr9Y.js
  → Browser sees a different URL → fetches the new file
  → Old cached main.BhJj3X.js is automatically abandoned

  This is why you can safely cache hashed assets for 1 year:
  The cache is NEVER invalidated (the URL just stops being used)

